# Let's use a smarter approach with early pruning

def find_costas_pruned(n):
    def backtrack(perm, used_rows, vectors):
        if len(perm) == n:
            return perm[:]

        for row in range(n):
            if row not in used_rows:
                # Check if adding this row creates any duplicate vectors
                valid = True
                new_vectors = []
                for i in range(len(perm)):
                    dc = len(perm) - i
                    dr = row - perm[i]
                    if (dc, dr) in vectors:
                        valid = False
                        break
                    new_vectors.append((dc, dr))

                if valid:
                    # Add new vectors
                    for v in new_vectors:
                        vectors.add(v)

                    perm.append(row)
                    used_rows.add(row)
                    result = backtrack(perm, used_rows, vectors)
                    if result is not None:
                        return result
                    perm.pop()
                    used_rows.remove(row)

                    # Remove new vectors
                    for v in new_vectors:
                        vectors.remove(v)
        return None

    return backtrack([], set(), set())

